import{_ as s,I as t,g as a,j as r}from"./chunks/framework.Ha9mtr6N.js";const u=JSON.parse('{"title":"Товары (Витрина)","description":"Управление складом готовой продукции, инвентаризация и FIFO-себестоимость в ОмниКрафт ЕРП.","frontmatter":{"title":"Товары (Витрина)","description":"Управление складом готовой продукции, инвентаризация и FIFO-себестоимость в ОмниКрафт ЕРП.","order":8},"headers":[],"relativePath":"ru/docs/spaces/production/showcase.md","filePath":"ru/docs/spaces/production/showcase.md"}'),e={name:"ru/docs/spaces/production/showcase.md"};function l(i,o,n,c,p,d){return t(),a("div",null,[...o[0]||(o[0]=[r('<div class="warning custom-block"><p class="custom-block-title">📌 Документация находится в разработке</p><p><strong>Уважаемые пользователи!</strong></p><p>Поскольку ОмниКрафт ЕРП сейчас находится в стадии активной бета-версии, регулярно дорабатывается и расширяется, справочные материалы также обновляются постепенно.</p><p>На данный момент воспринимайте документацию как ориентировочную — она является неполной, может временно не содержать описание некоторых функций или содержать неточности.</p></div><h1 id="🛒-товары-витрина-и-склад-готовои-продукции" tabindex="-1">🛒 Товары: Витрина и склад готовой продукции <a class="header-anchor" href="#🛒-товары-витрина-и-склад-готовои-продукции" aria-label="Permalink to &quot;🛒 Товары: Витрина и склад готовой продукции&quot;">​</a></h1><p>Вкладка <strong>«Товары»</strong> — это ваша виртуальная витрина. Здесь отображается актуальный физический остаток всех произведенных вами изделий, их текущая себестоимость и рекомендуемая цена для продажи.</p><p>Товары не появляются здесь из воздуха. Чтобы товар появился на витрине, он должен пройти через вкладку <a href="./workbench">«В производстве»</a> (быть сшитым на Верстаке).</p><hr><h2 id="📋-карточка-товара" tabindex="-1">📋 Карточка товара <a class="header-anchor" href="#📋-карточка-товара" aria-label="Permalink to &quot;📋 Карточка товара&quot;">​</a></h2><p>Каждое изделие представлено в виде наглядной карточки, на которой собрана вся критически важная информация:</p><ul><li><strong>В наличии:</strong> Текущий физический остаток на складе.</li><li><strong>Всего произведено:</strong> Исторический счетчик (сколько таких изделий вы сшили за всё время работы в программе).</li><li><strong>Рекомендуемая розничная цена (РРЦ):</strong> Цена, которую программа автоматически вычислила на базе себестоимости и вашей Глобальной наценки (из Настроек).</li></ul><h3 id="двоиная-себестоимость-по-калькулятору-vs-фактическая" tabindex="-1">Двойная себестоимость (По калькулятору vs Фактическая) <a class="header-anchor" href="#двоиная-себестоимость-по-калькулятору-vs-фактическая" aria-label="Permalink to &quot;Двойная себестоимость (По калькулятору vs Фактическая)&quot;">​</a></h3><p>Если у вас есть товар в наличии, на карточке вы увидите сразу две цифры себестоимости:</p><ol><li><strong>По калькулятору:</strong> Это <em>теоретическая</em> себестоимость изделия, если бы вы начали шить его прямо сейчас из текущих запасов сырья.</li><li><strong>Себестоимость остатка:</strong> Это <em>фактическая</em> себестоимость тех конкретных изделий, которые лежат у вас на полке в данный момент. Она берется из тех партий, которые вы реально сшили ранее.</li></ol><div class="info custom-block"><p class="custom-block-title">Зачем нужны две себестоимости? (Метод FIFO)</p><p>Представьте: вы сшили сумку месяц назад, когда кожа стоила дешево. Себестоимость той сумки составила 3 000 ₽. Сумка легла на полку. Сегодня кожа сильно подорожала. Калькулятор показывает, что сшить такую же сумку сейчас стоит 5 000 ₽. Если бы программа просто обновила цену старой сумки до 5 000 ₽, ваша прибыль при продаже исказилась бы. ОмниКрафт ЕРП так не делает. Программа помнит, что на полке лежит именно та, старая сумка за 3 000 ₽, и при продаже спишет именно эту цифру, обеспечив вам 100% точность расчета чистой прибыли. Это называется методом <strong>FIFO (First In, First Out)</strong>.</p></div><hr><h2 id="⚖️-инвентаризация-изделии" tabindex="-1">⚖️ Инвентаризация изделий <a class="header-anchor" href="#⚖️-инвентаризация-изделии" aria-label="Permalink to &quot;⚖️ Инвентаризация изделий&quot;">​</a></h2><p>Как и на складе сырья, физическая реальность иногда расходится с данными в программе (например, вы подарили кошелек другу и забыли это отметить, или наоборот, нашли на полке брелок, который забыли зачислить с верстака).</p><p>Для исправления таких ситуаций на каждой карточке товара есть кнопка <strong>«Инвентаризация»</strong>.</p><ol><li>Выберите тип: <strong>Оприходовать излишек (+)</strong> или <strong>Списать недостачу (-)</strong>.</li><li>Укажите количество штук.</li><li>Нажмите «Сохранить».</li></ol><h3 id="как-инвентаризация-влияет-на-финансы" tabindex="-1">Как инвентаризация влияет на финансы? <a class="header-anchor" href="#как-инвентаризация-влияет-на-финансы" aria-label="Permalink to &quot;Как инвентаризация влияет на финансы?&quot;">​</a></h3><p>Инвентаризация готовых товаров <strong>абсолютно безопасна для кассы</strong>.</p><ul><li>При списании недостачи программа просто удалит самые старые партии товара (по FIFO) со склада. Деньги из ДДС не спишутся, так как это просто корректировка учета.</li><li>При оприходовании излишка программа добавит товар на полку, присвоив ему <em>текущую оценочную себестоимость</em> из Калькулятора.</li></ul><div class="warning custom-block"><p class="custom-block-title">Не используйте инвентаризацию для продаж!</p><p>Списание недостачи просто удаляет товар со склада, не принося вам выручки. Если вы отдали товар клиенту, всегда проводите это через вкладку <strong>«Продажи»</strong>, даже если вы сделали 100% скидку (в этом случае просто укажите цену продажи 0 ₽, и программа честно зафиксирует убыток на себестоимость этого товара).</p></div>',21)])])}const g=s(e,[["render",l]]);export{u as __pageData,g as default};
